const SCHEMA = `
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schema_version (
  version INTEGER NOT NULL
);

-- The built-in task store.
CREATE TABLE IF NOT EXISTS task (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL,
  state      TEXT NOT NULL CHECK (state IN ('queued','running','done','failed','cancelled')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,

/** Every connection's wait at SQLite's lock boundary, in milliseconds. */
const CONCURRENT_WRITER_WAIT_MS = 5000;

/** A brief competing CLI/worker write queues at SQLite's lock boundary.
 * This is per connection, including non-migrating desktop/MCP connections.
 * It does not replay a transaction body or conceal a persistent lock. */
function waitForConcurrentWriter(db: Database): void {
  db.exec(`PRAGMA busy_timeout = ${CONCURRENT_WRITER_WAIT_MS}`);
}

/** How long one BEGIN IMMEDIATE attempt in beginWriteWithin sits in
 * SQLite's busy handler before the clock is consulted — nominal ms, so
 * brief contention still queues inside SQLite without a round trip. */
const WRITE_WAIT_SLICE_MS = 100;

/** SQLITE_BUSY in its primary or any extended form (node:sqlite reports
 * the extended code as `errcode`; the low byte is the primary code). */
function isDatabaseBusy(error: unknown): boolean {
  const code = (error as { errcode?: unknown } | null)?.errcode;
  return typeof code === "number" && (code & 0xff) === 5;

 * Open the database, creating it and its directory if needed. The import is
 * inside the function rather than at the top of the file so that a command
 * which never touches the store — every command that exists today — neither
 * loads SQLite nor pays its warning.
 */
export function openStore(file: string, options: OpenOptions = {}): Store {
  const connect = options.connect ?? defaultConnect;
  // The database's directory is 0700 from birth (round-2 finding 5 — the
  // DESIGN.md threat boundary is a claim only if the modes are real).
  if (file !== ":memory:") mkdirSync(dirname(file), { recursive: true, mode: 0o700 });

  const db = connect(file);
  try {
    waitForConcurrentWriter(db);
    return initializeStore(db, file);
  } catch (error) {
    // An unsuccessful open must not retain an unfinished migration's lock
    // for the lifetime of a long-running caller.
    try { db.close(); } catch { /* Preserve the original opening failure. */ }
    throw error;
  }
}

function initializeStore(db: Database, file: string): Store {
  // THE EPOCH, BEFORE ANY DDL (implementation review, finding 3): even
  // the fresh-SCHEMA exec below adds this build's new tables and indexes
  // to an old database, so the sentinel commits FIRST — a non-migrating
  // reader must never see new shapes under an old positive version.
  // THE PREFLIGHT (v48 integrity): the version is read as EXACTLY ONE
  // safe, supported integer before any DDL — one row, a safe integer,
  // its magnitude between 1 and this build's version. A database with no
  // version table is a fresh file; anything else (two rows, a text or
  // fractional version, a newer build's version, a zero) refuses here,
  // with the file untouched, rather than running this build's DDL over a
  // shape it cannot name.
  const preflight = schemaVersionPreflight(db, file);
  // Check existing authority metadata before even stamping a migration.
  if (preflight !== null && Math.abs(preflight) >= 54) {
    for (const table of ["approver", "invite"]) {
      if (!db.prepare(`PRAGMA table_info(${table})`).all().some(row => row["name"] === "projects_json")) {
        throw new Error(`${file}: project access metadata is missing from ${table}; refusing to widen access`);
      }
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 55 && db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='plan_authorization'").get() === undefined) {
    throw new Error(`${file}: plan authorization metadata is missing; refusing to recreate authority`);
  }
  if (preflight !== null && Math.abs(preflight) >= 56) {
    for (const table of ["workflow_recipe", "workflow_preview"]) {
      if (db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(table) === undefined) throw new Error(`${file}: workflow recipe metadata is missing; refusing to recreate launch history`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 58) {
    for (const table of ["learning_capture", "learning_policy", "project_lesson", "learning_event", "learning_snapshot"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: learning history is missing; refusing to recreate authority`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 59) {
    for (const table of ["project_knowledge", "knowledge_change", "knowledge_snapshot"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: project knowledge history is missing; refusing to recreate it`);
    }
  }
  // THE SENTINEL IS A CHECKED COMPARE-AND-SET (raw authority repair): the
  // row moves from exactly the version the preflight read to its negative,
  // or this open refuses — a second migrator that raced this one between
  // the preflight and here has already moved the row, and nothing alters a
  // file whose version it did not read.
  if (preflight !== null && Math.abs(preflight) >= 61) {
    for (const table of ["notification_delivery", "telegram_outbound_message", "telegram_retry"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: Telegram delivery history is missing; refusing to recreate receipts`);
    }
    for (const column of ["provenance_scope", "project", "task_ref", "task_id", "source_run"]) {
      if (!hasColumn(db, "notification", column)) throw new Error(`${file}: notification provenance is missing; refusing to recreate authority`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 62) {
    for (const table of ["telegram_conversation", "telegram_proposal_action"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: Telegram conversation history is missing; refusing to recreate it`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 63) {
    if (!tableExists(db, "telegram_conversation_part")) throw new Error(`${file}: Telegram reply history is missing; refusing to recreate it`);
  }
  if (preflight !== null && Math.abs(preflight) >= 64) {
    if (!tableExists(db, "mate_turn_evidence") || !hasColumn(db, "telegram_conversation_part", "artifact")) throw new Error(`${file}: Telegram image history is missing; refusing to recreate it`);
  }
  if (preflight !== null && Math.abs(preflight) >= 65) {
    for (const table of ["skill_package", "skill_owner", "project_skill_change", "skill_snapshot", "skill_test"]) {
      if (!tableExists(db, table)) throw new Error(`${file}: saved skills are missing; refusing to recreate them`);
    }
  }
  if (preflight !== null && Math.abs(preflight) >= 66) {
    const ddl = db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name='mate_proposal'").get()?.["sql"];
    if (typeof ddl !== "string" || canonicalDdl(ddl) !== canonicalDdl(MATE_PROPOSAL_V66_DDL("mate_proposal"))) throw new Error(`${file}: shared action history has an unknown shape; refusing to recreate it`);
  }
  if (preflight !== null && preflight > 0 && preflight < SCHEMA_VERSION) {
    const stamped = db.prepare("UPDATE schema_version SET version = ? WHERE version = ?").run(-preflight, preflight);
    if (Number(stamped.changes) !== 1) {
      throw new Error(`${file}: refusing to open — the schema version moved from v${preflight} between the preflight and the epoch stamp (another process is migrating it); this build speaks schema v${SCHEMA_VERSION} and alters nothing it cannot name`);
    }
  }
  db.exec(SCHEMA);
  db.exec(LEARNING_SCHEMA);
  db.exec(KNOWLEDGE_SCHEMA);
  db.exec(SKILLS_SCHEMA);
  migrate(db, preflight === null ? null : Math.abs(preflight));
  addColumn(db, "approver", "projects_json", "TEXT");
  addColumn(db, "invite", "projects_json", "TEXT");
  db.exec(LEDGER_SCHEMA);
  db.exec(RECIPE_SCHEMA);
  db.exec(PLAN_AUTO_SCHEMA);
  installLedgerTriggers(db);

/** Say which repository a task's work lives in. */
/**
 * Placement is immutable once a scope exists: an approval restates a goal
 * *for a project*, and moving the task afterwards would re-aim the yes at
 * a repo nobody agreed to. Place first, then scope — or requeue a fresh
 * task. (Console v2 review, finding 3.)
 */
placeTask(
  taskRef: number,
  repo: string,
  mutation: Mutation = {},
  now?: Date,
): boolean | { ok: false; reason: "scoped" } {
  return this.once(mutation, "placeTask", () => {
    return this.transact(() => {
      const external = this.db
        .prepare("SELECT external_id, repo FROM task_ref WHERE id = ?")
        .get(taskRef);
      const already = external === undefined || external["repo"] === null ? null : String(external["repo"]);
      if (external !== undefined) {
        const scoped = this.db
          .prepare("SELECT 1 AS hit FROM task_scope WHERE task_id = ?")
          .get(String(external["external_id"]));
        if (scoped !== undefined && already !== repo) {
          return { ok: false as const, reason: "scoped" as const };
        }
      }
      const { changes } = this.db
        .prepare("UPDATE task_ref SET repo = ? WHERE id = ?")
        .run(repo, taskRef);
      // Filing speaks once the project is known (Telegram task updates):
      // the FIRST placement is the moment a task becomes deliverable to
      // that project's phones, whichever door filed it — console form,
      // CLI add, a proposal, a revision, a routine firing, an external
      // mirror. A same-repo repeat changes nothing and says nothing.
      if (Number(changes) > 0 && external !== undefined && already === null) {
        const taskId = String(external["external_id"]);
        const task = this.db.prepare("SELECT title FROM task WHERE id = ?").get(taskId);
        const title = task === undefined ? taskId : String(task["title"]);
        this.noteLifecycle(
          { taskRef, kind: "task-filed", identity: `t${taskRef}`, subject: `New task: ${lifecycleWords(title, 80)}`, body: "Filed and waiting in the queue.", link: chatControlHref("task", taskId) },
          now ?? mutation.at ?? new Date(),
        );
      }
      return Number(changes) > 0;

/**
 * Multi-line prose may contain newlines and tabs; nothing anywhere in a
 * decision may contain the rest of C0/C1 — those are how text stops being
 * text and starts being terminal escape sequences.
 */
// eslint-disable-next-line no-control-regex
const FORBIDDEN_MULTILINE = /[\u0000-\u0008\u000B-\u001F\u007F-\u009F]/;
// eslint-disable-next-line no-control-regex
const FORBIDDEN_SINGLE_LINE = /[\u0000-\u001F\u007F-\u009F]/;

/** Whether text carries controls that could become escapes at a sink. Newlines and tabs pass. */
export function hasForbiddenControls(text: string): boolean {
  return FORBIDDEN_MULTILINE.test(text);
}

/**
 * Controls OR direction-override invisibles — the full disguise kit. For
 * text that becomes standing authority or a task identity (setup commands,
 * imported issue titles): a title reading "fix docs" while spelled
 * backwards is not a title, it is a costume.
 */
export function hasDisguisedText(text: string): boolean {
  return FORBIDDEN_MULTILINE.test(text) || FORBIDDEN_INVISIBLES.test(text);
}

const parent = options.directory ?? tmpdir();
mkdirSync(parent, { recursive: true });
const root = realpathSync(mkdtempSync(join(parent, 'standing-orders-ui-polish-')));
const repo = join(root, 'portfolio-console');
seedRepo(repo, 'portfolio-console', options.git !== false);
// The second project (workspace package 1): a deliberately long path so
// a phone task list has something to wrap, and so All-projects rows
// span two projects and must wear their labels.
const repo2 = options.secondProject === true
  ? join(root, 'clients', 'northwind-operations', 'ops-console-with-a-very-long-repository-name-for-overflow-checks')
  : null;
if (repo2 !== null) seedRepo(repo2, 'ops-console', options.git !== false);
// An enrolled project with no tasks at all, for the empty Work views.
const repo3 = options.secondProject === true ? join(root, 'clients', 'empty-sandbox') : null;
if (repo3 !== null) seedRepo(repo3, 'empty-sandbox', options.git !== false);
const evidenceRoot = join(root, 'evidence');
mkdirSync(evidenceRoot, { recursive: true });

const store = openStore(':memory:');

  const runId = store.startRun({
    taskRef: ref, leaseId: `fixture-lease-${id}`, runner: 'night-shift-2',
    branch: `standing-orders/${id}`, worktree: join(where, `.fixture-worktree-${id}`), now: hoursAgo(at + 1),
    provider: 'codex', model: 'default',
    ...(route === null ? {} : { route: { routeDigest: routeDigestOf(route), phase: 'build', provider: legOf(route, 'build').provider, model: legOf(route, 'build').model, chosen: legOf(route, 'build').chosen } }),
  });
  store.stampRun(runId, { baseRevision: '4b825dc642cb6eb9a060e54bf8d69288fbee4904', scopeDigest: scope.digest });
  const proof = facts.overclaim === true ? { ...PROOF, changed: [...PROOF.changed, 'src/ledger.ts'] } : PROOF;
  // The capture status is the plane's own (exit 0): a review request
  // reads it before it spends the run's bounded review allowance.
  storeEvidence(store, evidenceRoot, runId, 'terminal-diff', 'terminal-diff.patch', Buffer.from(PATCH, 'utf8'), 'git diff --no-ext-diff --no-textconv --no-color 4b825dc6..HEAD (exit 0) [fixture: synthetic]', hoursAgo(at + 0.2), { captureStatus: 'ok' });
  storeEvidence(store, evidenceRoot, runId, 'diff-stat', 'diff-stat.json', budgetedStatJson(stat), 'parsed from git diff --numstat -z [fixture: synthetic]', hoursAgo(at + 0.2));
  storeEvidence(store, evidenceRoot, runId, 'handoff', 'handoff.json', Buffer.from(JSON.stringify(HANDOFF, null, 2), 'utf8'), 'composed at completion [fixture: synthetic]', hoursAgo(at + 0.1));
  if (facts.noProof !== true) {
    storeEvidence(store, evidenceRoot, runId, 'proof', 'proof.json', Buffer.from(JSON.stringify(proof, null, 2), 'utf8'), 'agent-authored proof (validated) [fixture: synthetic]', hoursAgo(at + 0.1));
    storeEvidence(store, evidenceRoot, runId, 'screenshot', 'screenshot-fixture.png', png, 'agent-claimed screenshot at evidence/payout-dashboard.png (validated png) [fixture: synthetic]', hoursAgo(at + 0.1));
  }
  const verify = facts.verify ?? { configured: true, ran: true, exitCode: 0 };
  if (verify.configured && verify.ran) {
    storeEvidence(store, evidenceRoot, runId, 'check-log', 'check-log.txt', Buffer.from(`$ npm test\n(exit ${verify.exitCode})\n\n--- stdout ---\n${verify.exitCode === 0 ? '214 tests passed.' : '213 passed, 1 failed: settle rounds half-cents up (expected 31.16, got 31.15).'}\n\n--- stderr ---\n`, 'utf8'), `sh -c "npm test" (exit ${verify.exitCode}) [fixture: synthetic]`, hoursAgo(at + 0.1));
  }
  const verdict = adjudicate({
    proofArtifactPresent: facts.noProof !== true, proofParse: facts.noProof === true ? null : parseProof(JSON.stringify(proof)),
    handoffPresent: true, terminalDiffPresent: true, terminalDiffCaptureStatus: 'ok',
    diffStat: { captured: true, truncated: false, paths: new Set(stat.files.map(one => one.path)) },
    verifyCommand: verify,
    screenshots: facts.noProof === true ? [] : [{ path: 'evidence/payout-dashboard.png', ok: true, bytes: png.length, dims: imageDimensions(png, 'png') }],
    approvedCriteria: scope.acceptance,
  });
  store.saveProofVerdict(runId, verdict.verdict, verdict.reasons, hoursAgo(at), verdict.matrix);
  store.finishRun(runId, { outcome: 'built', committed: true, now: hoursAgo(at) });
  store.setTaskState(id, 'done', hoursAgo(at));
  if (facts.accept !== undefined) store.acceptProof(runId, 'polish-fixture', facts.accept, hoursAgo(at - 0.1));
  if (facts.publication !== undefined) {
    const publicationId = store.createPublicationIntent({
      run: runId, taskRef: ref, githubRepo: 'northwind/ops-console', remote: 'origin', base: 'main', head: `standing-orders/${id}`,
      headSha: '9e07b4152aa01c9f3d7700e54bf8d69288fbe777', bodyHash: 'fixture', draft: false,
    }, hoursAgo(at - 0.05));
    store.markPublicationPushed(publicationId, hoursAgo(at - 0.06));
    store.markPublicationOpened(publicationId, facts.publication.pr, `https://github.com/northwind/ops-console/pull/${facts.publication.pr}`, hoursAgo(at - 0.07));
    if (facts.publication.checks) store.recordPublicationCheckState(publicationId, facts.publication.checks, hoursAgo(at - 0.08));
    if (facts.publication.remote) store.recordPublicationRemoteState(publicationId, facts.publication.remote, hoursAgo(at - 0.09));
  }
  return { taskId: id, runId, ref };
};
const queued = (id, title, at, facts = {}) => {
  const where = facts.repo ?? repo;
  const filed = fileTaskProposal(store, {
    id, title, repo: where,
    goal: facts.goal ?? `${title}. Keep every current column name so downstream spreadsheets keep working.`,
    outOfScope: 'No settlement engine changes.', touches: ['src/export/csv.ts', 'src/export/csv.test.ts'],
    acceptance: [{ id: 'c1', statement: 'The exported CSV parses with a standard CSV reader.', how: null, evidence: ['check'] }],
    filedVia: 'console', planning: 'skip',
  }, hoursAgo(at));
  if (!filed.ok) throw new Error(`fixture ${id}: ${filed.reason}`);
  const scope = store.getScope(id);
  if (facts.approve !== false) approve(store, id, 'polish-fixture', hoursAgo(at - 0.1), scope.digest, login.token);
  return { taskId: id, ref: store.refFor('built-in', id).id, scope: store.getScope(id) };
};
const results = {};
results.failedChecks = finished('csv-quoting', options.statusPresentation ? 'Escape quotes in the CSV writer while preserving every long Japanese 日本語 column name and the full assessment path in the settlement export' : 'Escape quotes in the CSV writer', 6, { verify: { configured: true, ran: true, exitCode: 1 } });
results.mismatched = finished('range-filter', 'Make the date-range filter inclusive', 7, { overclaim: true });
results.missingProof = finished('subtotal-rows', 'Add per-currency subtotal rows', 8, { noProof: true });
results.attested = finished('excel-bom', options.revisionNames ? LONG_REVISION_PARENT : 'Emit a UTF-8 BOM for Excel exports', 9, { verify: { configured: false } });
results.accepted = finished('export-button', 'Keep the export button keyboard reachable', 10, { noProof: true, accept: 'Checked the export button by hand on two browsers; the proof file was lost when the worktree was cleaned.' });
results.published = finished('settlement-rounding', 'Round settlement totals at cent precision', 11, { repo: repo2 ?? repo, publication: { pr: 482, checks: 'passing' } });

  const captureLearning = () => {
    const source = store.getRun(run), when = new Date();
    const asked = store.requestReview(run, 'polish-fixture', when);
    if (!asked.ok) throw new Error(`synthetic learning review: ${asked.reason}`);
    const reviewer = store.startRun({ taskRef: source.taskRef, role: 'reviewer', parentRun: run, request: asked.id, leaseId: 'synthetic-learning-review', runner: 'reviewer-1', provider: 'codex', model: 'default', now: when, ...liveRoute('payout-rounding', 'review') });
    store.stampProviderStart(reviewer, when);
    const artifact = store.artifactsFor(run).find(a => a.kind === 'terminal-diff');
    const candidate = { kind: 'project', observation: 'Payout rounding uses cent precision.', action: 'Keep half-cent boundary cases in payout tests.', paths: ['src/payout.ts'], phases: ['plan', 'build', 'review'], evidence: [{ artifactId: artifact.id, sha256: artifact.sha256, excerpt: '+  return Math.round(cents * rate * 100) / 100;' }] };
    learningContext(store, evidenceRoot, reviewer, 'review', when);
    queueLearning(store, run, reviewer, [candidate, { ...candidate, kind: 'system', observation: 'Synthetic long-detail boundary: ' + 'source-reference-'.repeat(25), action: 'Keep review context bounded and inspectable. This is a tracked suggestion only.' }], [artifact].map(a => ({ artifactId: a.id, sha256: a.sha256 })), when);
    store.finishRun(reviewer, { outcome: 'no-change', reason: 'reviewed — synthetic learning fixture', now: when });
    recoverLearning(store, evidenceRoot, repo, when);
  };
  let learningOrdinal = 0;
  const laterLearningRun = () => {
    const id = `later-learning-${++learningOrdinal}`, when = new Date();
    const filed = fileTaskProposal(store, { id, title: 'Later payout boundary check (synthetic)', repo, goal: 'Inspect payout boundary tests.', outOfScope: 'No unrelated changes.', touches: ['src/payout.ts'], acceptance: [{ id: 'c1', statement: 'Payout boundary tests remain meaningful.', how: null, evidence: ['check'] }], filedVia: 'console', planning: 'skip' }, when);
    if (!filed.ok) throw new Error(filed.reason);
    approve(store, id, 'polish-fixture', when, store.getScope(id).digest, login.token);
    const runId = store.startRun({ taskRef: store.lookupRef(id).id, runner: 'night-shift-1', leaseId: `fixture-learning-${id}`, branch: `standing-orders/${id}`, worktree: repo, provider: 'codex', model: 'default', now: when, ...liveRoute(id, 'build') });
    store.stampRun(runId, { baseRevision: stat.head, scopeDigest: store.getScope(id).digest });
    const context = learningContext(store, evidenceRoot, runId, 'build', when);
    store.finishRun(runId, { outcome: 'no-change', reason: 'Synthetic context supplied; no model invoked', now: when });
    return { runId, context };
